const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>LeaseLimit \u2014 Rent Affordability Calculator: 30% Rule, 40\u00d7 Rule &amp; True Cost</title>\n<meta name=\"description\" content=\"LeaseLimit is a free rent affordability calculator that compares the 30% rule, the landlord 40\u00d7 rule, and your custom net budget side by side \u2014 adding utilities, parking, insurance and pet fees BEFORE the verdict, plus move-in cash and roommate splits.\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<style>\n  html{scroll-behavior:smooth}\n  body{font-family:ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif}\n  .num{font-variant-numeric:tabular-nums}\n  .brick{color:#9A3412}\n  .bg-brick{background-color:#9A3412}\n  .bg-brick-dark{background-color:#7C2D12}\n  .border-brick{border-color:#9A3412}\n  .ring-brick:focus{--tw-ring-color:#9A3412}\n  input[type=range]{accent-color:#9A3412}\n  .toggle{width:52px;height:28px;border-radius:9999px;background:#CBD5E1;position:relative;cursor:pointer;transition:background .2s;flex:none}\n  .toggle::after{content:\"\";position:absolute;top:3px;left:3px;width:22px;height:22px;border-radius:9999px;background:#fff;transition:left .2s;box-shadow:0 1px 3px rgba(0,0,0,.3)}\n  .toggle[aria-checked=\"true\"]{background:#9A3412}\n  .toggle[aria-checked=\"true\"]::after{left:27px}\n  .stackbar{height:12px;border-radius:9999px;overflow:hidden;display:flex;background:#F1F5F9}\n  .faq-a{max-height:0;overflow:hidden;transition:max-height .3s ease}\n</style>\n</head>\n<body class=\"bg-[#FFF7ED] text-slate-700\" id=\"top\">\n\n<!-- ======================= STICKY HEADER ======================= -->\n<header class=\"sticky top-0 z-40 bg-[#FFF7ED]/95 backdrop-blur border-b-2 border-[#9A3412]\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 h-16 flex items-center justify-between\">\n    <a href=\"#top\" class=\"flex items-center gap-2\">\n      <span class=\"w-9 h-9 rounded-xl bg-brick text-white grid place-items-center font-black text-xl shadow\">L</span>\n      <span class=\"text-2xl font-black tracking-tight text-slate-800\">Lease<span class=\"brick\">Limit</span></span>\n    </a>\n    <nav class=\"flex items-center gap-5 text-sm font-semibold\">\n      <a href=\"#top\" class=\"text-slate-600 hover:text-[#9A3412]\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"bg-brick hover:bg-brick-dark text-white px-4 py-2 rounded-full transition\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<!-- ======================= HERO ======================= -->\n<section class=\"mx-auto max-w-6xl px-4 sm:px-6 pt-10 pb-6 text-center\">\n  <span class=\"inline-flex items-center gap-2 bg-[#9A3412]/10 border border-[#9A3412]/30 text-[#9A3412] text-xs font-bold uppercase tracking-widest px-4 py-1.5 rounded-full\">\n    <span class=\"w-2 h-2 rounded-full bg-brick animate-pulse\"></span> Unlimited Free Usage\n  </span>\n  <h1 class=\"mt-5 text-4xl sm:text-5xl font-black text-slate-900 tracking-tight\">How Much Rent Can You <span class=\"brick\">Really</span> Afford?</h1>\n  <p class=\"mt-4 max-w-2xl mx-auto text-slate-600 text-lg\">Three proven methods, side by side. LeaseLimit subtracts your <strong class=\"text-slate-800\">real recurring housing costs</strong> \u2014 utilities, parking, insurance, pet fees \u2014 <strong class=\"text-slate-800\">before</strong> giving the verdict, then tells you the cash you need to move in.</p>\n</section>\n\n<!-- TOP AD (verbatim) -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ======================= TOOL ======================= -->\n<main id=\"tool\" class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8\">\n\n  <!-- STEP 1: INCOME -->\n  <section class=\"bg-white rounded-3xl shadow-xl border border-orange-100 p-6 sm:p-8\">\n    <div class=\"flex flex-wrap items-center justify-between gap-3\">\n      <h2 class=\"text-xl font-black text-slate-900\"><span class=\"brick\">\u2460</span> Your income &amp; budget</h2>\n      <label class=\"flex items-center gap-2 text-sm font-semibold text-slate-600\">Currency\n        <select id=\"currency\" class=\"border border-slate-300 rounded-lg px-2 py-1.5 bg-white focus:ring-2 ring-brick outline-none\">\n          <option value=\"$\" selected>$ USD</option>\n          <option value=\"\u20ac\">\u20ac EUR</option>\n          <option value=\"\u00a3\">\u00a3 GBP</option>\n          <option value=\"\u20b9\">\u20b9 INR</option>\n          <option value=\"CA$\">CA$ CAD</option>\n          <option value=\"A$\">A$ AUD</option>\n        </select>\n      </label>\n    </div>\n    <div class=\"grid sm:grid-cols-2 lg:grid-cols-4 gap-4 mt-5\">\n      <label class=\"block\">\n        <span class=\"text-sm font-bold text-slate-700\">Gross monthly income <span class=\"text-slate-400 font-normal\">(before tax)</span></span>\n        <input id=\"gross\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"e.g. 6,000\" class=\"num mt-1.5 w-full border-2 border-slate-200 rounded-xl px-4 py-3 text-lg font-bold text-slate-900 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none\">\n      </label>\n      <label class=\"block\">\n        <span class=\"text-sm font-bold text-slate-700\">Net monthly income <span class=\"text-slate-400 font-normal\">(take-home)</span></span>\n        <input id=\"net\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"optional\" class=\"num mt-1.5 w-full border-2 border-slate-200 rounded-xl px-4 py-3 text-lg font-bold text-slate-900 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none\">\n      </label>\n      <label class=\"block\">\n        <span class=\"text-sm font-bold text-slate-700\">Other monthly expenses <span class=\"text-slate-400 font-normal\">(non-housing)</span></span>\n        <input id=\"otherExp\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"food, debt, transit\u2026\" class=\"num mt-1.5 w-full border-2 border-slate-200 rounded-xl px-4 py-3 text-lg font-bold text-slate-900 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none\">\n      </label>\n      <label class=\"block\">\n        <span class=\"text-sm font-bold text-slate-700\">Monthly savings target</span>\n        <input id=\"savings\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"e.g. 500\" class=\"num mt-1.5 w-full border-2 border-slate-200 rounded-xl px-4 py-3 text-lg font-bold text-slate-900 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none\">\n      </label>\n    </div>\n    <div class=\"mt-5 flex items-center justify-between gap-4 bg-[#FFF7ED] border border-orange-200 rounded-2xl px-5 py-4\">\n      <div>\n        <p class=\"font-bold text-slate-900\">Roommate scenario</p>\n        <p class=\"text-sm text-slate-500\">Split the recurring housing costs 2 ways. The verdict below shows <strong>your share</strong> of the rent.</p>\n      </div>\n      <div id=\"roommateToggle\" class=\"toggle\" role=\"switch\" aria-checked=\"false\" tabindex=\"0\" aria-label=\"Roommate scenario\"></div>\n    </div>\n  </section>\n\n  <!-- VERDICT HERO -->\n  <section class=\"mt-6 rounded-3xl shadow-2xl overflow-hidden\">\n    <div class=\"bg-gradient-to-br from-[#7C2D12] via-[#9A3412] to-[#C2410C] text-white p-6 sm:p-10\">\n      <div class=\"flex flex-wrap items-center justify-between gap-4\">\n        <div>\n          <p class=\"text-orange-200 text-sm font-bold uppercase tracking-widest\">Your verdict \u2014 max affordable rent</p>\n          <p class=\"num text-5xl sm:text-7xl font-black mt-2 tracking-tight\"><span id=\"curSym\">$</span><span id=\"verdictRent\">0</span><span class=\"text-2xl sm:text-3xl font-bold text-orange-200\">/mo</span></p>\n          <p id=\"verdictSub\" class=\"mt-3 text-orange-100/90 text-sm sm:text-base max-w-xl\">Enter your income above to get your verdict.</p>\n        </div>\n        <div class=\"bg-white/10 backdrop-blur rounded-2xl px-6 py-5 text-center border border-white/20\">\n          <p class=\"text-xs uppercase tracking-widest text-orange-200 font-bold\">Housing burden</p>\n          <p class=\"num text-3xl font-black mt-1\"><span id=\"burdenPct\">0</span>%</p>\n          <p id=\"burdenLabel\" class=\"text-sm text-orange-100/90 mt-1\">of gross income</p>\n        </div>\n      </div>\n      <div class=\"mt-6 flex flex-wrap gap-2 text-xs font-bold\">\n        <span class=\"bg-white/15 border border-white/25 rounded-full px-3 py-1.5\">\u2460 30% rule: <span class=\"num\" id=\"heroM1\">\u2014</span></span>\n        <span class=\"bg-white/15 border border-white/25 rounded-full px-3 py-1.5\">\u2461 40\u00d7 rule: <span class=\"num\" id=\"heroM2\">\u2014</span></span>\n        <span class=\"bg-white/15 border border-white/25 rounded-full px-3 py-1.5\">\u2462 Net budget: <span class=\"num\" id=\"heroM3\">\u2014</span></span>\n        <span class=\"bg-white/15 border border-white/25 rounded-full px-3 py-1.5\">\u2212 Cost stack: <span class=\"num\" id=\"heroStack\">\u2014</span></span>\n      </div>\n    </div>\n  </section>\n\n  <!-- STEP 2: METHOD COMPARISON -->\n  <section class=\"mt-10\">\n    <h2 class=\"text-2xl font-black text-slate-900\"><span class=\"brick\">\u2461</span> The 3 methods, side by side</h2>\n    <p class=\"text-slate-500 mt-1\">Each method gives a max <strong>total housing budget</strong>. Your cost stack is subtracted afterwards \u2014 the verdict is the most conservative one.</p>\n    <div class=\"grid md:grid-cols-3 gap-5 mt-5\">\n      <article class=\"bg-white rounded-2xl shadow-lg border-t-4 border-[#9A3412] p-6\">\n        <p class=\"text-xs font-black uppercase tracking-widest text-[#9A3412]\">Method 1 \u00b7 The classic</p>\n        <h3 class=\"text-lg font-black text-slate-900 mt-1\">30% gross-income rule</h3>\n        <p class=\"text-sm text-slate-500 mt-2\">Spend no more than 30% of your gross monthly income on total housing.</p>\n        <p class=\"num text-4xl font-black text-slate-900 mt-4\"><span class=\"curS\">$</span><span id=\"m1Rent\">0</span><span class=\"text-base font-bold text-slate-400\">/mo</span></p>\n        <p class=\"text-xs text-slate-400 mt-2 num\" id=\"m1Math\">gross \u00d7 0.30</p>\n      </article>\n      <article class=\"bg-white rounded-2xl shadow-lg border-t-4 border-slate-500 p-6\">\n        <p class=\"text-xs font-black uppercase tracking-widest text-slate-500\">Method 2 \u00b7 Landlord gate</p>\n        <h3 class=\"text-lg font-black text-slate-900 mt-1\">40\u00d7 annual-rent rule</h3>\n        <p class=\"text-sm text-slate-500 mt-2\">Landlords often require annual income \u2265 40\u00d7 the monthly rent.</p>\n        <p class=\"num text-4xl font-black text-slate-900 mt-4\"><span class=\"curS\">$</span><span id=\"m2Rent\">0</span><span class=\"text-base font-bold text-slate-400\">/mo</span></p>\n        <p class=\"text-xs text-slate-400 mt-2 num\" id=\"m2Math\">annual income \u00f7 40</p>\n      </article>\n      <article class=\"bg-white rounded-2xl shadow-lg border-t-4 border-emerald-600 p-6\">\n        <p class=\"text-xs font-black uppercase tracking-widest text-emerald-700\">Method 3 \u00b7 Cash-flow truth</p>\n        <h3 class=\"text-lg font-black text-slate-900 mt-1\">Custom net budget</h3>\n        <p class=\"text-sm text-slate-500 mt-2\">Net income minus your other expenses and savings target.</p>\n        <p class=\"num text-4xl font-black text-slate-900 mt-4\"><span class=\"curS\">$</span><span id=\"m3Rent\">0</span><span class=\"text-base font-bold text-slate-400\">/mo</span></p>\n        <p class=\"text-xs text-slate-400 mt-2 num\" id=\"m3Math\">net \u2212 expenses \u2212 savings</p>\n      </article>\n    </div>\n    <div id=\"verdictNote\" class=\"mt-4 bg-[#9A3412]/5 border border-[#9A3412]/25 rounded-2xl px-5 py-4 text-sm text-slate-700\"></div>\n  </section>\n\n  <!-- STEP 3: COST STACK -->\n  <section class=\"mt-10 bg-white rounded-3xl shadow-xl border border-orange-100 p-6 sm:p-8\">\n    <h2 class=\"text-xl font-black text-slate-900\"><span class=\"brick\">\u2462</span> Your recurring housing-cost stack</h2>\n    <p class=\"text-slate-500 mt-1 text-sm\">Most calculators show a rent number and <em>then</em> mention utilities. LeaseLimit subtracts these <strong class=\"text-slate-700\">first</strong> \u2014 because the verdict is about the rent you can sign for, not the rent plus surprises.</p>\n    <div class=\"grid sm:grid-cols-2 lg:grid-cols-4 gap-4 mt-5\">\n      <label class=\"block bg-[#FFF7ED] rounded-2xl p-4 border border-orange-200\">\n        <span class=\"text-sm font-bold text-slate-700\">\u26a1 Utilities <span class=\"font-normal text-slate-400\">/mo</span></span>\n        <input id=\"util\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"electric, water, gas, net\" class=\"num mt-1.5 w-full border border-slate-200 rounded-lg px-3 py-2.5 font-bold text-slate-900 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none bg-white\">\n      </label>\n      <label class=\"block bg-[#FFF7ED] rounded-2xl p-4 border border-orange-200\">\n        <span class=\"text-sm font-bold text-slate-700\">\ud83c\udd7f\ufe0f Parking <span class=\"font-normal text-slate-400\">/mo</span></span>\n        <input id=\"park\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"garage / permit\" class=\"num mt-1.5 w-full border border-slate-200 rounded-lg px-3 py-2.5 font-bold text-slate-900 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none bg-white\">\n      </label>\n      <label class=\"block bg-[#FFF7ED] rounded-2xl p-4 border border-orange-200\">\n        <span class=\"text-sm font-bold text-slate-700\">\ud83d\udee1\ufe0f Renter's insurance <span class=\"font-normal text-slate-400\">/mo</span></span>\n        <input id=\"ins\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"contents cover\" class=\"num mt-1.5 w-full border border-slate-200 rounded-lg px-3 py-2.5 font-bold text-slate-900 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none bg-white\">\n      </label>\n      <label class=\"block bg-[#FFF7ED] rounded-2xl p-4 border border-orange-200\">\n        <span class=\"text-sm font-bold text-slate-700\">\ud83d\udc3e Pet fees <span class=\"font-normal text-slate-400\">/mo</span></span>\n        <input id=\"pet\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"pet rent\" class=\"num mt-1.5 w-full border border-slate-200 rounded-lg px-3 py-2.5 font-bold text-slate-900 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none bg-white\">\n      </label>\n    </div>\n    <div class=\"mt-6\">\n      <div class=\"flex items-center justify-between text-sm font-bold\">\n        <span class=\"text-slate-600\">Total cost stack <span id=\"stackNote\" class=\"font-normal text-slate-400\">(your full cost)</span></span>\n        <span class=\"num text-2xl font-black text-slate-900\"><span class=\"curS\">$</span><span id=\"stackTotal\">0</span><span class=\"text-sm font-bold text-slate-400\">/mo</span></span>\n      </div>\n      <div class=\"stackbar mt-3\">\n        <div id=\"barUtil\" class=\"bg-amber-500\" style=\"width:0%\"></div>\n        <div id=\"barPark\" class=\"bg-sky-500\" style=\"width:0%\"></div>\n        <div id=\"barIns\" class=\"bg-emerald-500\" style=\"width:0%\"></div>\n        <div id=\"barPet\" class=\"bg-rose-400\" style=\"width:0%\"></div>\n      </div>\n      <div class=\"flex flex-wrap gap-x-5 gap-y-1 mt-2 text-xs font-semibold text-slate-500\">\n        <span><span class=\"inline-block w-2.5 h-2.5 rounded-sm bg-amber-500 mr-1\"></span>Utilities <span class=\"num\" id=\"pctUtil\">0%</span></span>\n        <span><span class=\"inline-block w-2.5 h-2.5 rounded-sm bg-sky-500 mr-1\"></span>Parking <span class=\"num\" id=\"pctPark\">0%</span></span>\n        <span><span class=\"inline-block w-2.5 h-2.5 rounded-sm bg-emerald-500 mr-1\"></span>Insurance <span class=\"num\" id=\"pctIns\">0%</span></span>\n        <span><span class=\"inline-block w-2.5 h-2.5 rounded-sm bg-rose-400 mr-1\"></span>Pet fees <span class=\"num\" id=\"pctPet\">0%</span></span>\n      </div>\n    </div>\n  </section>\n\n  <!-- STEP 4: MOVE-IN CASH -->\n  <section class=\"mt-10 bg-slate-800 text-slate-100 rounded-3xl shadow-xl p-6 sm:p-8\">\n    <h2 class=\"text-xl font-black text-white\"><span class=\"text-orange-400\">\u2463</span> Move-in cash calculator</h2>\n    <p class=\"text-slate-400 mt-1 text-sm\">The rent is only part of signing a lease. Based on your verdict rent (editable), here's the cash you need on day one.</p>\n    <div class=\"grid sm:grid-cols-2 lg:grid-cols-3 gap-4 mt-5\">\n      <label class=\"block bg-slate-700/60 rounded-2xl p-4\">\n        <span class=\"text-sm font-bold text-slate-200\">Target monthly rent</span>\n        <input id=\"targetRent\" type=\"number\" min=\"0\" inputmode=\"decimal\" class=\"num mt-1.5 w-full border border-slate-600 rounded-lg px-3 py-2.5 font-bold text-white bg-slate-900 focus:border-orange-400 outline-none\">\n        <span class=\"text-xs text-slate-400\">auto-filled from your verdict \u2014 edit freely</span>\n      </label>\n      <label class=\"block bg-slate-700/60 rounded-2xl p-4\">\n        <span class=\"text-sm font-bold text-slate-200\">Security deposit</span>\n        <select id=\"depositMonths\" class=\"mt-1.5 w-full border border-slate-600 rounded-lg px-3 py-2.5 font-bold text-white bg-slate-900 focus:border-orange-400 outline-none\">\n          <option value=\"0\">No deposit</option>\n          <option value=\"0.5\">\u00bd month</option>\n          <option value=\"1\" selected>1 month</option>\n          <option value=\"1.5\">1\u00bd months</option>\n          <option value=\"2\">2 months</option>\n        </select>\n      </label>\n      <label class=\"block bg-slate-700/60 rounded-2xl p-4\">\n        <span class=\"text-sm font-bold text-slate-200\">Broker / agent fee <span class=\"font-normal text-slate-400\">(% of annual rent)</span></span>\n        <input id=\"brokerPct\" type=\"number\" min=\"0\" max=\"100\" inputmode=\"decimal\" placeholder=\"0\" class=\"num mt-1.5 w-full border border-slate-600 rounded-lg px-3 py-2.5 font-bold text-white bg-slate-900 focus:border-orange-400 outline-none\">\n      </label>\n      <label class=\"block bg-slate-700/60 rounded-2xl p-4\">\n        <span class=\"text-sm font-bold text-slate-200\">Moving costs</span>\n        <input id=\"moving\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"movers, truck, boxes\" class=\"num mt-1.5 w-full border border-slate-600 rounded-lg px-3 py-2.5 font-bold text-white bg-slate-900 focus:border-orange-400 outline-none\">\n      </label>\n      <label class=\"block bg-slate-700/60 rounded-2xl p-4\">\n        <span class=\"text-sm font-bold text-slate-200\">Application &amp; admin fees</span>\n        <input id=\"appFees\" type=\"number\" min=\"0\" inputmode=\"decimal\" placeholder=\"one-time fees\" class=\"num mt-1.5 w-full border border-slate-600 rounded-lg px-3 py-2.5 font-bold text-white bg-slate-900 focus:border-orange-400 outline-none\">\n      </label>\n      <div class=\"bg-slate-700/60 rounded-2xl p-4 flex flex-col justify-center gap-4\">\n        <div class=\"flex items-center justify-between gap-3\">\n          <span class=\"text-sm font-bold text-slate-200\">First month's rent</span>\n          <div id=\"firstToggle\" class=\"toggle\" role=\"switch\" aria-checked=\"true\" tabindex=\"0\" aria-label=\"Include first month\"></div>\n        </div>\n        <div class=\"flex items-center justify-between gap-3\">\n          <span class=\"text-sm font-bold text-slate-200\">Last month's rent</span>\n          <div id=\"lastToggle\" class=\"toggle\" role=\"switch\" aria-checked=\"false\" tabindex=\"0\" aria-label=\"Include last month\"></div>\n        </div>\n      </div>\n    </div>\n    <div class=\"mt-6 bg-slate-900 rounded-2xl p-5\">\n      <div class=\"flex items-center justify-between\">\n        <p class=\"text-sm font-bold uppercase tracking-widest text-slate-400\">Total cash needed to move in</p>\n        <p class=\"num text-4xl font-black text-orange-400\"><span class=\"curS\">$</span><span id=\"moveInTotal\">0</span></p>\n      </div>\n      <ul id=\"moveInList\" class=\"mt-4 space-y-2 text-sm\"></ul>\n    </div>\n  </section>\n\n  <!-- STEP 5: SAVE SCENARIO -->\n  <section class=\"mt-10 bg-white rounded-3xl shadow-xl border border-orange-100 p-6 sm:p-8\">\n    <h2 class=\"text-xl font-black text-slate-900\"><span class=\"brick\">\u2464</span> Save this scenario</h2>\n    <p class=\"text-slate-500 text-sm mt-1\">Compare neighborhoods or lease offers later \u2014 saved privately in your browser.</p>\n    <div class=\"flex flex-col sm:flex-row gap-3 mt-4\">\n      <input id=\"scenarioName\" type=\"text\" maxlength=\"60\" placeholder=\"e.g. Downtown 2BR vs Suburb 1BR\" class=\"flex-1 border-2 border-slate-200 rounded-xl px-4 py-3 focus:border-[#9A3412] focus:ring-2 ring-brick outline-none\">\n      <button id=\"saveBtn\" class=\"bg-brick hover:bg-brick-dark text-white font-bold px-6 py-3 rounded-xl transition\">Save scenario</button>\n    </div>\n    <ul id=\"scenarioList\" class=\"mt-4 space-y-2\"></ul>\n  </section>\n\n</main>\n\n<!-- BOTTOM AD (verbatim) -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<!-- ======================= SEO ARTICLE ======================= -->\n<!-- SEO-ARTICLE-START -->\n<article class=\"mx-auto max-w-4xl px-4 sm:px-6 py-10 prose-slate\">\n  <h2 class=\"text-3xl font-black text-slate-900\">The Complete Guide to Rent Affordability: Rules, True Costs, and Smart Leasing</h2>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">Why \"how much rent can I afford\" is the wrong question to ask first</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">Most renters start apartment hunting with a single number in mind: the monthly rent they think they can pay. That number almost always comes from a rule of thumb, and it almost always ignores the costs that actually break budgets. A rent affordability calculator that only multiplies your income by 30 percent is doing you a disservice, because rent is just the headline figure on a much longer invoice. The true monthly cost of a home includes utilities, parking, renter's insurance, pet fees, and sometimes mandatory service charges \u2014 and the true day-one cost includes a security deposit, broker fees, first and last month's rent, application fees, and moving expenses. LeaseLimit was built to answer the question properly: after every recurring housing cost is subtracted first, what rent can you actually sign for without financial stress?</p>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">Method 1: the 30 percent rule rent calculator approach</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">The 30 percent rule is the most quoted guideline in personal finance: spend no more than 30 percent of your gross monthly income on housing. It traces back to mid-20th-century US housing policy, when 25 percent was considered the ceiling; the threshold was raised to 30 percent in the 1980s and has stuck ever since. If you earn $6,000 a month before tax, the 30 percent rule says your total housing budget is $1,800 a month. Note the word <em>total</em>: the rule was always meant to cover rent plus utilities, not rent alone. That is where most people go wrong \u2014 they find a $1,800 apartment, then discover another $250 in utilities and parking on top, and suddenly they are spending 34 percent of their income on housing. A proper 30 percent rule rent calculator subtracts those recurring costs from the budget before naming an affordable rent, which is exactly what LeaseLimit does.</p>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">Method 2: the 40x annual rent rule landlords actually use</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">Here is the rule that decides whether your application gets approved. In competitive rental markets \u2014 New York being the famous example \u2014 landlords require your gross annual income to be at least 40 times the monthly rent. Earn $80,000 a year? The most expensive apartment you can qualify for is $2,000 a month ($80,000 \u00f7 40). Mathematically, the 40x rule equals the 30 percent rule: annual income divided by 40 is the same as monthly gross income times 0.3. But knowing it as a separate rule matters, because landlords apply it as a hard gate, not a suggestion. If the 40x rule says you qualify for $2,000 but your own budget says $1,700 is comfortable, the landlord's number does not make $2,000 wise \u2014 it only makes it possible. LeaseLimit shows both numbers side by side so you can see the gap between \"approved\" and \"affordable.\"</p>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">Method 3: the custom net-budget method (the cash-flow truth)</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">Gross income is what you earn; net income is what you keep. The custom net-budget method starts from your actual take-home pay, subtracts every non-housing expense \u2014 groceries, transport, debt payments, subscriptions, childcare \u2014 and subtracts your savings target too. Whatever remains is the maximum you can spend on housing without borrowing from your future. This is the most honest of the three methods and often the most conservative, especially for people with heavy student-loan or car payments. If your net pay is $4,200, your non-housing expenses are $2,100, and you want to save $500, your net-budget housing ceiling is $1,600 \u2014 even if the 30 percent rule on a $6,500 gross salary says $1,950. When the methods disagree, the safe move is to trust the lowest number. That is why LeaseLimit's verdict is always the most conservative of the three, after the cost stack is removed.</p>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">The recurring housing-cost stack: the costs everyone forgets</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">Ask a renter what their apartment costs and they will quote the rent. Ask them again after six months and the answer changes. The recurring housing-cost stack is everything you pay every month just to keep living there: electricity, gas, water, trash, and internet (easily $150\u2013$300 combined in many cities); parking or garage fees ($50\u2013$300, and often mandatory in new buildings); renter's insurance ($10\u2013$30 a month, and increasingly required by leases); and pet rent ($25\u2013$75 per pet per month in pet-friendly buildings, sometimes with a separate pet deposit). These are not optional lifestyle costs \u2014 they are contract costs. A $1,500 apartment with a $220 cost stack is really a $1,720-a-month commitment. Subtract the stack first, and your affordable rent drops to $1,280 under the 30 percent rule on a $5,000 salary. That gap is the difference between a comfortable lease and a stretched one, and it is why LeaseLimit puts the cost stack before the verdict instead of burying it in fine print.</p>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">Move-in cash: the number that surprises first-time renters</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">Signing a lease requires cash on day one that has nothing to do with your monthly budget. The typical move-in stack includes the security deposit (often one full month's rent, sometimes more), the first month's rent, and in many markets the last month's rent too. Add a broker or agent fee \u2014 commonly 8 to 15 percent of the annual rent in cities like New York and Boston \u2014 plus application and administrative fees ($50\u2013$150 per applicant), pet deposits, and the physical cost of moving itself (a few hundred dollars for a DIY move, $1,000+ for movers). It is completely normal for move-in cash to equal three to four months of rent. On a $1,800 apartment, that is $5,400\u2013$7,200 due before you spend a single night there. LeaseLimit's move-in cash calculator itemizes every one of these line items from your target rent so you can save the lump sum before you start touring.</p>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">The roommate equation: splitting costs the right way</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">A roommate does not just halve your rent \u2014 a roommate halves your entire housing-cost stack. Utilities, parking, insurance, and pet fees all get split, which means the per-person cost of a $2,000 two-bedroom with a $300 stack is $1,150 each, not $1,000. That distinction matters when you compare a solo one-bedroom against sharing a larger place. The right way to run the math is to split the stack first, then subtract your half from your personal housing budget \u2014 never split the verdict rent itself, because your budget is yours alone. Toggle the roommate scenario in LeaseLimit and the verdict automatically switches to your share, so you can compare \"solo\" and \"shared\" numbers with one click.</p>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">How to use this apartment affordability calculator</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">Start with your gross monthly income \u2014 the number the 30 percent and 40x rules need. Add your net take-home pay plus your other monthly expenses and savings target to unlock the custom net-budget method; the more honest these inputs, the more honest the verdict. Next, fill in your recurring cost stack as accurately as you can: check a utility bill, ask the building about parking, get a renter's insurance quote (they take five minutes), and confirm pet fees in writing. Watch the verdict update live. Then scroll to the move-in cash calculator, confirm the target rent, and see your day-one number. Finally, save the scenario \u2014 run a few versions for different neighborhoods or lease offers and compare them side by side before you sign anything. The whole exercise takes five minutes and can save you from a twelve-month financial mistake.</p>\n\n  <h3 class=\"text-xl font-black text-slate-900 mt-8\">Beyond the rules: when to break them (carefully)</h3>\n  <p class=\"mt-3 text-slate-600 leading-relaxed\">Rules of thumb are starting points, not laws. Spending 35 percent of gross income on housing can be perfectly sensible if you have no debt, cook at home, and walk to work \u2014 and 25 percent can still be reckless if you are carrying high-interest debt. High-cost cities routinely push renters past 30 percent; the question is never \"am I over the line?\" but \"what am I trading for it?\" If a pricier apartment near work eliminates a $300 car payment and two hours of commuting, the effective math may favor it. Conversely, stretching for space you will barely use is the classic budget killer. Use the three-method verdict as your anchor, treat the cost stack as non-negotiable, keep an emergency fund that covers at least the move-in cash figure, and re-run the calculator every time your income or expenses change. Affordability is not a number you compute once \u2014 it is a habit you keep.</p>\n</article>\n<!-- SEO-ARTICLE-END -->\n\n<!-- ======================= FAQS ======================= -->\n<section class=\"mx-auto max-w-4xl px-4 sm:px-6 pb-6\">\n  <h2 class=\"text-3xl font-black text-slate-900\">Frequently asked questions</h2>\n  <div class=\"mt-6 space-y-3\" id=\"faqWrap\">\n    <div class=\"faq-item bg-white rounded-2xl shadow border border-orange-100 overflow-hidden\">\n      <button class=\"faq-q w-full text-left px-6 py-4 font-bold text-slate-900 flex justify-between items-center gap-3\">How much rent can I afford based on my income?<span class=\"brick text-xl\">+</span></button>\n      <div class=\"faq-a px-6\"><p class=\"pb-5 text-slate-600\">The standard answer is 30% of your gross monthly income for total housing costs. On a $5,000 monthly salary that is $1,500 \u2014 but that must cover rent <em>plus</em> utilities, parking, insurance and pet fees, not rent alone. LeaseLimit subtracts those recurring costs first, then compares the 30% rule, the 40x landlord rule, and your custom net budget to give the most conservative verdict.</p></div>\n    </div>\n    <div class=\"faq-item bg-white rounded-2xl shadow border border-orange-100 overflow-hidden\">\n      <button class=\"faq-q w-full text-left px-6 py-4 font-bold text-slate-900 flex justify-between items-center gap-3\">What is the 40x rent rule that landlords use?<span class=\"brick text-xl\">+</span></button>\n      <div class=\"faq-a px-6\"><p class=\"pb-5 text-slate-600\">The 40x rule requires your gross annual income to be at least 40 times the monthly rent \u2014 so a $90,000 salary qualifies you for up to $2,250/month. It is mathematically identical to the 30% rule (annual income \u00f7 40 = monthly gross \u00d7 0.30), but landlords use it as a hard approval gate. Passing the 40x rule means you qualify; it does not mean the rent is comfortable for your budget.</p></div>\n    </div>\n    <div class=\"faq-item bg-white rounded-2xl shadow border border-orange-100 overflow-hidden\">\n      <button class=\"faq-q w-full text-left px-6 py-4 font-bold text-slate-900 flex justify-between items-center gap-3\">Should utilities count toward the 30% rule?<span class=\"brick text-xl\">+</span></button>\n      <div class=\"faq-a px-6\"><p class=\"pb-5 text-slate-600\">Yes \u2014 the 30% guideline was always meant to cover total housing costs, not rent alone. Utilities, parking, renter's insurance and pet fees are recurring contract costs that can add $150\u2013$400+ a month. A rent affordability calculator with utilities subtracts this cost stack before naming an affordable rent, which is the honest way to run the math and the approach LeaseLimit uses.</p></div>\n    </div>\n    <div class=\"faq-item bg-white rounded-2xl shadow border border-orange-100 overflow-hidden\">\n      <button class=\"faq-q w-full text-left px-6 py-4 font-bold text-slate-900 flex justify-between items-center gap-3\">How much cash do I need to move into an apartment?<span class=\"brick text-xl\">+</span></button>\n      <div class=\"faq-a px-6\"><p class=\"pb-5 text-slate-600\">Plan for 3\u20134 months of rent in cash: a security deposit (usually one month), first month's rent, sometimes last month's rent, a broker fee of 8\u201315% of annual rent in broker-heavy markets, application and admin fees, pet deposits, and moving costs. On an $1,800 apartment that is typically $5,400\u2013$7,200 due on day one. Use the move-in cash calculator above to itemize it for your target rent.</p></div>\n    </div>\n    <div class=\"faq-item bg-white rounded-2xl shadow border border-orange-100 overflow-hidden\">\n      <button class=\"faq-q w-full text-left px-6 py-4 font-bold text-slate-900 flex justify-between items-center gap-3\">Does getting a roommate change how much rent I can afford?<span class=\"brick text-xl\">+</span></button>\n      <div class=\"faq-a px-6\"><p class=\"pb-5 text-slate-600\">Yes \u2014 a roommate splits not just the rent but the entire cost stack: utilities, parking, insurance and pet fees. The correct math is to halve the stack first, then subtract your half from your personal housing budget. Turn on the roommate toggle above and the verdict switches to your share automatically, so you can compare solo versus shared living with one click.</p></div>\n    </div>\n    <div class=\"faq-item bg-white rounded-2xl shadow border border-orange-100 overflow-hidden\">\n      <button class=\"faq-q w-full text-left px-6 py-4 font-bold text-slate-900 flex justify-between items-center gap-3\">Is the 30% rule based on gross or net income?<span class=\"brick text-xl\">+</span></button>\n      <div class=\"faq-a px-6\"><p class=\"pb-5 text-slate-600\">The traditional 30% rule and the 40x rule both use gross (pre-tax) income. But gross income is not what lands in your account, which is why the custom net-budget method exists: take-home pay minus other expenses minus savings equals your true housing ceiling. When the methods disagree, the net-budget number is usually the one to trust, and it is the most conservative input to LeaseLimit's final verdict.</p></div>\n    </div>\n  </div>\n</section>\n\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How much rent can I afford based on my income?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"The standard answer is 30% of your gross monthly income for total housing costs. On a $5,000 monthly salary that is $1,500 \u2014 but that must cover rent plus utilities, parking, insurance and pet fees, not rent alone. Subtract those recurring costs first, then compare the 30% rule, the 40x landlord rule, and your custom net budget, and take the most conservative result.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What is the 40x rent rule that landlords use?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"The 40x rule requires your gross annual income to be at least 40 times the monthly rent \u2014 so a $90,000 salary qualifies you for up to $2,250/month. It is mathematically identical to the 30% rule, but landlords use it as a hard approval gate. Passing it means you qualify, not that the rent is comfortable.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Should utilities count toward the 30% rule?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Yes \u2014 the 30% guideline was always meant to cover total housing costs, not rent alone. Utilities, parking, renter's insurance and pet fees are recurring contract costs that can add $150\u2013$400+ a month. Subtract this cost stack before naming an affordable rent for an honest result.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How much cash do I need to move into an apartment?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Plan for 3\u20134 months of rent in cash: a security deposit (usually one month), first month's rent, sometimes last month's rent, a broker fee of 8\u201315% of annual rent in broker-heavy markets, application and admin fees, pet deposits, and moving costs. On an $1,800 apartment that is typically $5,400\u2013$7,200 due on day one.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Does getting a roommate change how much rent I can afford?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Yes \u2014 a roommate splits not just the rent but the entire cost stack: utilities, parking, insurance and pet fees. Halve the stack first, then subtract your half from your personal housing budget. The verdict then shows your share of the rent.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Is the 30% rule based on gross or net income?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"The traditional 30% rule and the 40x rule both use gross (pre-tax) income. But the custom net-budget method \u2014 take-home pay minus other expenses minus savings \u2014 gives your true housing ceiling, and when the methods disagree it is usually the one to trust.\" }\n    }\n  ]\n}\n</script>\n\n<footer class=\"border-t border-orange-200 mt-8\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 flex flex-col sm:flex-row items-center justify-between gap-3 text-sm text-slate-500\">\n    <p><span class=\"font-black text-slate-800\">LeaseLimit</span> \u2014 free rent affordability calculator. Unlimited free usage, no signup.</p>\n    <p class=\"text-xs max-w-md text-center sm:text-right\">Estimates only, not financial advice. Always verify costs with the property before signing a lease.</p>\n  </div>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n\n<!-- PURE LOGIC (no DOM) \u2014 extracted by Node tests -->\n<script id=\"ll-logic\">\nvar LeaseLimit = (function () {\n  \"use strict\";\n  function num(v) {\n    if (v === null || v === undefined) return 0;\n    var n = parseFloat(String(v).replace(/[^0-9.\\-]/g, \"\"));\n    return (isFinite(n) && n > 0) ? n : 0;\n  }\n  function round2(n) { return Math.round((num(n) + Number.EPSILON) * 100) / 100; }\n\n  // Method 1: 30% of gross monthly income\n  function method30(grossMonthly) { return round2(num(grossMonthly) * 0.30); }\n  // Method 2: landlord 40x rule \u2014 annual gross income / 40\n  function method40x(grossMonthly) { return round2(num(grossMonthly) * 12 / 40); }\n  // Method 3: custom net budget \u2014 take-home minus other expenses minus savings\n  function methodCustom(netMonthly, otherExpenses, savingsTarget) {\n    return round2(Math.max(0, num(netMonthly) - num(otherExpenses) - num(savingsTarget)));\n  }\n\n  // Recurring housing-cost stack (utilities + parking + insurance + pet fees)\n  function costStack(c) {\n    return round2(num(c.utilities) + num(c.parking) + num(c.insurance) + num(c.petFees));\n  }\n  // Roommate splits the stack 2 ways\n  function stackShare(stack, roommate) { return round2(num(stack) / (roommate ? 2 : 1)); }\n\n  // Affordable rent for one method AFTER the cost stack is subtracted\n  function rentAfterStack(methodBudget, stack, roommate) {\n    return round2(Math.max(0, num(methodBudget) - stackShare(stack, roommate)));\n  }\n\n  // Final verdict: most conservative ACTIVE method (budget > 0), stack subtracted first\n  function verdict(budgets, stack, roommate) {\n    var active = budgets.map(num).filter(function (b) { return b > 0; });\n    if (!active.length) return 0;\n    var conservative = Math.min.apply(null, active);\n    return round2(Math.max(0, conservative - stackShare(stack, roommate)));\n  }\n\n  // Housing burden % = (rent + stack) / gross\n  function burdenPct(grossMonthly, rent, stack) {\n    var g = num(grossMonthly);\n    if (g <= 0) return 0;\n    return round2((num(rent) + num(stack)) / g * 100);\n  }\n\n  // Move-in cash: deposit + broker fee + first/last month + moving + app fees\n  function moveInCash(o) {\n    var rent = num(o.rent);\n    var items = [\n      { label: \"Security deposit\", amount: round2(rent * num(o.depositMonths)) },\n      { label: \"Broker / agent fee\", amount: round2(rent * 12 * num(o.brokerPct) / 100) },\n      { label: \"First month's rent\", amount: o.includeFirst ? rent : 0 },\n      { label: \"Last month's rent\", amount: o.includeLast ? rent : 0 },\n      { label: \"Moving costs\", amount: round2(num(o.moving)) },\n      { label: \"Application & admin fees\", amount: round2(num(o.appFees)) }\n    ];\n    var total = round2(items.reduce(function (s, i) { return s + num(i.amount); }, 0));\n    return { items: items, total: total };\n  }\n\n  function burdenLabel(pct) {\n    if (pct <= 0) return \"of gross income\";\n    if (pct <= 25) return \"of gross income \u2014 comfortable\";\n    if (pct <= 30) return \"of gross income \u2014 healthy\";\n    if (pct <= 40) return \"of gross income \u2014 stretched\";\n    return \"of gross income \u2014 overextended\";\n  }\n\n  return {\n    num: num, round2: round2,\n    method30: method30, method40x: method40x, methodCustom: methodCustom,\n    costStack: costStack, stackShare: stackShare, rentAfterStack: rentAfterStack,\n    verdict: verdict, burdenPct: burdenPct, burdenLabel: burdenLabel, moveInCash: moveInCash\n  };\n})();\n</script>\n\n<script>\n(function () {\n  \"use strict\";\n  var L = LeaseLimit;\n  var $ = function (id) { return document.getElementById(id); };\n  var roommate = false, includeFirst = true, includeLast = false, targetRentDirty = false;\n  var CUR = \"$\";\n\n  function money(n) {\n    return L.round2(n).toLocaleString(\"en-US\", { minimumFractionDigits: 0, maximumFractionDigits: 0 });\n  }\n  function setCur() {\n    document.querySelectorAll(\".curS\").forEach(function (el) { el.textContent = CUR; });\n    $(\"curSym\").textContent = CUR;\n  }\n\n  function readInputs() {\n    return {\n      gross: L.num($(\"gross\").value), net: L.num($(\"net\").value),\n      otherExp: L.num($(\"otherExp\").value), savings: L.num($(\"savings\").value),\n      util: L.num($(\"util\").value), park: L.num($(\"park\").value),\n      ins: L.num($(\"ins\").value), pet: L.num($(\"pet\").value)\n    };\n  }\n\n  function calc() {\n    var v = readInputs();\n    var m1 = L.method30(v.gross), m2 = L.method40x(v.gross);\n    var m3 = (v.net > 0) ? L.methodCustom(v.net, v.otherExp, v.savings) : 0;\n    var stack = L.costStack({ utilities: v.util, parking: v.park, insurance: v.ins, petFees: v.pet });\n    var share = L.stackShare(stack, roommate);\n\n    var budgets = [m1, m2].concat(m3 > 0 ? [m3] : []);\n    var r1 = L.rentAfterStack(m1, stack, roommate),\n        r2 = L.rentAfterStack(m2, stack, roommate),\n        r3 = m3 > 0 ? L.rentAfterStack(m3, stack, roommate) : 0;\n    var ver = L.verdict(budgets, stack, roommate);\n\n    // Hero\n    $(\"verdictRent\").textContent = money(ver);\n    var burden = L.burdenPct(v.gross, ver, share);\n    $(\"burdenPct\").textContent = burden;\n    $(\"burdenLabel\").textContent = L.burdenLabel(burden);\n    $(\"verdictSub\").textContent = v.gross > 0\n      ? \"The most conservative of the 3 methods, after your \" + CUR + money(share) + \"/mo cost stack\" + (roommate ? \" (split 2 ways with your roommate)\" : \"\") + \". This is your share of the rent.\"\n      : \"Enter your income above to get your verdict.\";\n\n    $(\"heroM1\").textContent = CUR + money(r1);\n    $(\"heroM2\").textContent = CUR + money(r2);\n    $(\"heroM3\").textContent = m3 > 0 ? CUR + money(r3) : \"\u2014\";\n    $(\"heroStack\").textContent = CUR + money(share);\n\n    // Method cards\n    $(\"m1Rent\").textContent = money(r1);\n    $(\"m1Math\").textContent = CUR + money(v.gross) + \" \u00d7 0.30 \u2212 \" + CUR + money(share) + \" stack\";\n    $(\"m2Rent\").textContent = money(r2);\n    $(\"m2Math\").textContent = CUR + money(v.gross * 12) + \" \u00f7 40 \u2212 \" + CUR + money(share) + \" stack\";\n    $(\"m3Rent\").textContent = m3 > 0 ? money(r3) : \"0\";\n    $(\"m3Math\").textContent = m3 > 0\n      ? CUR + money(v.net) + \" \u2212 \" + CUR + money(v.otherExp) + \" \u2212 \" + CUR + money(v.savings) + \" \u2212 \" + CUR + money(share) + \" stack\"\n      : \"enter net income to unlock\";\n\n    var used = [\"30% rule\", \"40\u00d7 rule\"].concat(m3 > 0 ? [\"net budget\"] : []);\n    $(\"verdictNote\").innerHTML = v.gross > 0\n      ? \"<strong class='text-slate-900'>Verdict logic:</strong> compared \" + used.join(\" vs \") +\n        \" \u2192 most conservative housing budget is <strong>\" + CUR + money(Math.min.apply(null, budgets)) +\n        \"</strong>/mo. Subtracted your cost-stack share (<strong>\" + CUR + money(share) + \"</strong>/mo\" +\n        (roommate ? \", split 2 ways\" : \"\") + \") \u2192 affordable rent <strong class='brick'>\" + CUR + money(ver) + \"/mo</strong>.\"\n      : \"Your verdict will appear here once you enter a gross monthly income.\";\n\n    // Stack\n    $(\"stackTotal\").textContent = money(share);\n    $(\"stackNote\").textContent = roommate ? \"(your half \u2014 split 2 ways)\" : \"(your full cost)\";\n    var parts = [[\"Util\", v.util, \"barUtil\", \"pctUtil\"], [\"Park\", v.park, \"barPark\", \"pctPark\"], [\"Ins\", v.ins, \"barIns\", \"pctIns\"], [\"Pet\", v.pet, \"barPet\", \"pctPet\"]];\n    parts.forEach(function (p) {\n      var pct = stack > 0 ? (L.num(p[1]) / stack * 100) : 0;\n      $(p[2]).style.width = pct + \"%\";\n      $(p[3]).textContent = Math.round(pct) + \"%\";\n    });\n\n    // Move-in (target rent follows verdict unless user edited it)\n    if (!targetRentDirty) { $(\"targetRent\").value = ver > 0 ? Math.round(ver) : \"\"; }\n    var mi = L.moveInCash({\n      rent: L.num($(\"targetRent\").value),\n      depositMonths: parseFloat($(\"depositMonths\").value) || 0,\n      brokerPct: L.num($(\"brokerPct\").value),\n      includeFirst: includeFirst, includeLast: includeLast,\n      moving: L.num($(\"moving\").value), appFees: L.num($(\"appFees\").value)\n    });\n    $(\"moveInTotal\").textContent = money(mi.total);\n    $(\"moveInList\").innerHTML = mi.items.map(function (i) {\n      return \"<li class='flex justify-between gap-3'><span class='text-slate-300'>\" + i.label + \"</span><span class='num font-bold text-white'>\" + CUR + money(i.amount) + \"</span></li>\";\n    }).join(\"\");\n  }\n\n  // Toggles\n  function wireToggle(id, get, set) {\n    var el = $(id);\n    function flip() { set(!get()); el.setAttribute(\"aria-checked\", String(get())); calc(); }\n    el.addEventListener(\"click\", flip);\n    el.addEventListener(\"keydown\", function (e) { if (e.key === \" \" || e.key === \"Enter\") { e.preventDefault(); flip(); } });\n  }\n  wireToggle(\"roommateToggle\", function () { return roommate; }, function (x) { roommate = x; });\n  wireToggle(\"firstToggle\", function () { return includeFirst; }, function (x) { includeFirst = x; });\n  wireToggle(\"lastToggle\", function () { return includeLast; }, function (x) { includeLast = x; });\n\n  [\"gross\",\"net\",\"otherExp\",\"savings\",\"util\",\"park\",\"ins\",\"pet\",\"brokerPct\",\"moving\",\"appFees\",\"depositMonths\",\"targetRent\"].forEach(function (id) {\n    $(id).addEventListener(\"input\", function () { if (id === \"targetRent\") targetRentDirty = true; calc(); });\n    $(id).addEventListener(\"change\", calc);\n  });\n  $(\"currency\").addEventListener(\"change\", function () { CUR = $(\"currency\").value; setCur(); calc(); });\n\n  // Scenarios (localStorage)\n  var KEY = \"leaselimit.scenarios.v1\";\n  function loadSc() { try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { return []; } }\n  function saveSc(list) { try { localStorage.setItem(KEY, JSON.stringify(list)); } catch (e) {} }\n  function renderSc() {\n    var list = loadSc();\n    $(\"scenarioList\").innerHTML = list.length ? \"\" : \"<li class='text-sm text-slate-400'>No saved scenarios yet.</li>\";\n    list.forEach(function (s, i) {\n      var li = document.createElement(\"li\");\n      li.className = \"flex items-center justify-between gap-3 bg-[#FFF7ED] border border-orange-200 rounded-xl px-4 py-2.5\";\n      li.innerHTML = \"<span class='font-semibold text-slate-800 truncate'></span><span class='flex gap-2 flex-none'><button class='load text-xs font-bold bg-brick text-white px-3 py-1.5 rounded-lg'>Load</button><button class='del text-xs font-bold bg-slate-200 text-slate-700 px-3 py-1.5 rounded-lg'>Delete</button></span>\";\n      li.querySelector(\"span\").textContent = s.name;\n      li.querySelector(\".load\").addEventListener(\"click\", function () {\n        Object.keys(s.inputs).forEach(function (k) { if ($(k)) $(k).value = s.inputs[k]; });\n        roommate = !!s.roommate; $(\"roommateToggle\").setAttribute(\"aria-checked\", String(roommate));\n        targetRentDirty = false; calc();\n      });\n      li.querySelector(\".del\").addEventListener(\"click\", function () { var l = loadSc(); l.splice(i, 1); saveSc(l); renderSc(); });\n      $(\"scenarioList\").appendChild(li);\n    });\n  }\n  $(\"saveBtn\").addEventListener(\"click\", function () {\n    var name = $(\"scenarioName\").value.trim() || (\"Scenario \" + (loadSc().length + 1));\n    var inputs = {};\n    [\"gross\",\"net\",\"otherExp\",\"savings\",\"util\",\"park\",\"ins\",\"pet\",\"brokerPct\",\"moving\",\"appFees\",\"depositMonths\",\"targetRent\",\"currency\"].forEach(function (k) { inputs[k] = $(k).value; });\n    var list = loadSc(); list.push({ name: name, inputs: inputs, roommate: roommate, savedAt: Date.now() });\n    saveSc(list); $(\"scenarioName\").value = \"\"; renderSc();\n  });\n\n  // FAQs\n  document.querySelectorAll(\".faq-q\").forEach(function (btn) {\n    btn.addEventListener(\"click\", function () {\n      var a = btn.parentElement.querySelector(\".faq-a\");\n      var open = a.style.maxHeight && a.style.maxHeight !== \"0px\";\n      document.querySelectorAll(\".faq-a\").forEach(function (x) { x.style.maxHeight = \"0px\"; });\n      document.querySelectorAll(\".faq-q span\").forEach(function (x) { x.textContent = \"+\"; });\n      if (!open) { a.style.maxHeight = a.scrollHeight + \"px\"; btn.querySelector(\"span\").textContent = \"\u2212\"; }\n    });\n  });\n\n  setCur(); renderSc(); calc();\n})();\n</script>\n</body>\n</html>\n";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", { status: 404 });
    }
    return new Response(HTML, {
      headers: { "content-type": "text/html;charset=UTF-8" }
    });
  }
};